{
  "title": "Evidence-Based Analysis of Most Effective Hunger-Fighting Interventions",
  "content": "This plan researches and synthesizes evidence on the most cost-effective hunger interventions across multiple categories: (1) GiveWell-recommended charities and their cost-effectiveness models, (2) direct cash transfers (GiveDirectly), (3) large-scale humanitarian programs (WFP), (4) agricultural innovations (Golden Rice, biofortification), (5) high-tech food production (vertical farming), and (6) food waste reduction. Each research track runs in parallel, followed by a synthesis task that produces evidence-based rankings.",
  "tasks": [
    {
      "goal": "Research GiveWell's top-rated hunger and nutrition interventions: fetch GiveWell's cost-effectiveness models page, top charities page, and impact estimates page. Extract specific cost-per-life-saved and cost-per-DALY figures for nutrition-related charities (e.g., Helen Keller International vitamin A supplementation, malnutrition treatment programs, salt iodization). Include their methodology and how they compare interventions.",
      "tool_name": "spawn_sub_agent",
      "depends_on": []
    },
    {
      "goal": "Research GiveDirectly's effectiveness for hunger and poverty reduction: fetch their research page (givedirectly.org/research-on-cash-transfers/), their cost-effectiveness position paper PDF, and the UPenn impact evaluation. Extract specific figures on cost per household lifted from hunger, multiplier effects on food security, comparison vs in-kind food aid, and RCT evidence on nutrition outcomes from cash transfers.",
      "tool_name": "spawn_sub_agent",
      "depends_on": []
    },
    {
      "goal": "Research WFP program effectiveness and large-scale hunger interventions: fetch WFP impact evaluation pages, their cost-of-hunger analysis, and the 2025 anticipatory action evidence publication. Extract cost-per-beneficiary figures, cost-per-meal data, evidence on school feeding programs, emergency food assistance effectiveness, and how WFP compares to other delivery mechanisms.",
      "tool_name": "spawn_sub_agent",
      "depends_on": []
    },
    {
      "goal": "Research agricultural innovation effectiveness for fighting hunger: (1) Golden Rice - fetch the PMC article (PMC8713968) on cost-effectiveness and the Genetic Literacy Project analysis, extract cost-per-DALY and potential lives saved; (2) Biofortification broadly (HarvestPlus, iron beans, zinc wheat) - search for Copenhagen Consensus rankings and cost-effectiveness data; (3) Search for evidence on agricultural R&D return on investment for hunger reduction (CGIAR system impact).",
      "tool_name": "spawn_sub_agent",
      "depends_on": []
    },
    {
      "goal": "Research vertical farming and food waste reduction effectiveness for hunger: (1) Vertical farming - fetch recent analyses on cost-per-calorie vs traditional farming, current limitations for staple crops, and whether it addresses hunger or mainly serves premium markets; (2) Food waste reduction - fetch the WRI analysis on $14 saved per $1 invested, UNEP food waste data, and evidence on food rescue/redistribution programs (e.g., Feeding America cost-per-meal). Compare these approaches' scalability and impact on global hunger.",
      "tool_name": "spawn_sub_agent",
      "depends_on": []
    },
    {
      "goal": "Synthesize all research into a comprehensive evidence-based ranking of hunger interventions by cost-effectiveness. Create a structured analysis with: (1) Tier rankings of interventions by impact per dollar, (2) Comparison table with cost-per-DALY, cost-per-life-saved, or cost-per-beneficiary metrics where available, (3) Assessment of evidence quality for each intervention, (4) Analysis of which interventions address acute vs chronic hunger, (5) Key findings and recommendations. Note limitations and where evidence is weak.",
      "tool_name": "reasoning",
      "depends_on": [0, 1, 2, 3, 4]
    }
  ],
  "dependencies_graph": [
    {"task_idx": "0", "depends_on": []},
    {"task_idx": "1", "depends_on": []},
    {"task_idx": "2", "depends_on": []},
    {"task_idx": "3", "depends_on": []},
    {"task_idx": "4", "depends_on": []},
    {"task_idx": "5", "depends_on": ["0", "1", "2", "3", "4"]}
  ],
  "join": "all"
}
